if(condition)

If you were to issue an if() without a relational operator following such as we see in the code for the var()
If it returns TRUE then the code block runs and if it returns FALSE the block is skipped


var

function (x, y = NULL, na.rm = FALSE, use) 
{
    if (missing(use)) 
        use &lt;- if (na.rm) 
            "na.or.complete"
        else "everything"
    na.method &lt;- pmatch(use, c("all.obs", "complete.obs", "pairwise.complete.obs", 
        "everything", "na.or.complete"))
    if (is.na(na.method)) 
        stop("invalid 'use' argument")
    if (is.data.frame(x)) 
        x &lt;- as.matrix(x)
    else if (!is.null(x)) 
        stopifnot(is.atomic(x))
    if (is.data.frame(y)) 
        y &lt;- as.matrix(y)
    else if (!is.null(y)) 
        stopifnot(is.atomic(y))
    .Call(C_cov, x, y, na.method, FALSE)
}
